SELECT analytics_order_facts.quarter, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year IN (2025, 2026) AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'education' GROUP BY analytics_order_facts.quarter ORDER BY analytics_order_facts.quarter ASC LIMIT 24
